// Vendors packages/mentor-mascot/mascot.js and mascot.d.ts (owner M) into src/vendor/ so the web app builds
// from apps/web alone (the production Docker build context is apps/web). Runs before `pnpm dev` and
// `pnpm build`; when the source is missing (Docker), the committed copy is used as is.
// src/lib/mascotSync.test.ts fails when a copy drifts from its source.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const BANNER =
  "// GENERATED by apps/web/scripts/sync-mascot.mjs from packages/mentor-mascot (owner M). Edit the source, not this copy.\n";

const FILES = [
  ["mascot.js", "mentor-mascot.js"],
  ["mascot.d.ts", "mentor-mascot.d.ts"],
];

const srcDir = new URL("../../../packages/mentor-mascot/", import.meta.url);
const dstDir = new URL("../src/vendor/", import.meta.url);

for (const [from, to] of FILES) {
  const src = fileURLToPath(new URL(from, srcDir));
  const dst = fileURLToPath(new URL(to, dstDir));
  if (!existsSync(src)) {
    console.log(`sync-mascot: packages/mentor-mascot/${from} not found, keeping the vendored copy`);
    continue;
  }
  const body = BANNER + readFileSync(src, "utf8");
  if (!existsSync(dst) || readFileSync(dst, "utf8") !== body) {
    mkdirSync(fileURLToPath(dstDir), { recursive: true });
    writeFileSync(dst, body);
    console.log(`sync-mascot: updated src/vendor/${to}`);
  }
}
